select count(*) from offline_report


		and subbarcode =#{subbarcode}


		and tested_date like '%' #{tested_date} '%'


		and  status =#{status}

select report_id,subbarcode,person_name,tested_date, tested_by,report_filenameone,report_filenametwo,report_filenamethree,report_file_path,emailaddress,send_date,status,checked_by,checked_date,saleremail,supportemail,manageremail,pmemail
from offline_report


		and subbarcode =#{subbarcode}


		and tested_date like '%' #{tested_date} '%'


		and  status =#{status}


limit #{pageNo},#{pageSize}
